<template>
  <div class="container mt-5">
    <h2 class="text-center mb-4">Employee Management System</h2>

    <div class="card p-4 shadow mb-4">
      <h4>{{ isEditing ? "Update Employee" : "Add Employee" }}</h4>

      <form @submit.prevent="saveEmployee">
        <div class="row">
          <div class="col-md-3 mb-3">
            <input class="form-control" placeholder="Name" v-model="employee.name" required />
          </div>

          <div class="col-md-3 mb-3">
            <input class="form-control" placeholder="Designation" v-model="employee.designation" required />
          </div>

          <div class="col-md-3 mb-3">
            <input class="form-control" placeholder="Department" v-model="employee.department" required />
          </div>

          <div class="col-md-3 mb-3">
            <input type="number" class="form-control" placeholder="Salary" v-model.number="employee.salary" required />
          </div>
        </div>

        <button class="btn btn-primary">
          {{ isEditing ? "Update" : "Add" }}
        </button>

        <button type="button" class="btn btn-secondary ms-2" @click="resetForm">
          Clear
        </button>
      </form>
    </div>

    <div class="card p-4 shadow">
      <h4>Employee List ({{ employees.length }})</h4>

      <table class="table table-bordered table-hover mt-3">
        <thead class="table-dark">
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Designation</th>
            <th>Department</th>
            <th>Salary</th>
            <th>Actions</th>
          </tr>
        </thead>

        <tbody>
          <tr v-for="emp in employees" :key="emp.id">
            <td><strong>{{ emp.id }}</strong></td>
            <td>{{ emp.name }}</td>
            <td>{{ emp.designation }}</td>
            <td>{{ emp.department }}</td>
            <td>${{ parseFloat(emp.salary).toLocaleString() }}</td>
            <td>
              <button class="btn btn-warning btn-sm me-2" @click="editEmployee(emp)">
                Edit
              </button>
              <button class="btn btn-danger btn-sm" @click="deleteEmployee(emp.id)">
                Delete
              </button>
            </td>
          </tr>
        </tbody>
      </table>

      <p v-if="employees.length === 0" class="text-center text-muted">
        No employees found. Add one to start!
      </p>
      
      <button v-if="employees.length > 0" class="btn btn-danger mt-3 w-100" @click="clearAllEmployees">
        💥 Delete All Employees ({{ employees.length }})
      </button>
    </div>
  </div>
</template>

<script>
import axios from "axios";

export default {
  name: "EmployeeApp",
  data() {
    return {
      apiBase: "https://69e895f355d62f3479796589.mockapi.io/api",
      apiEndpoint: "employee",
      employees: [],
      employee: {
        id: null,
        name: "",
        designation: "",
        department: "",
        salary: 0,
      },
      isEditing: false,
    };
  },
  computed: {
    apiUrl() {
      return `${this.apiBase}/${this.apiEndpoint}`;
    }
  },
  mounted() {
    this.getEmployees();
  },
  methods: {
    async getEmployees() {
      try {
        const response = await axios.get(this.apiUrl);
        this.employees = response.data || [];
      } catch (error) {
        console.error('GET employees failed:', error);
        this.employees = [];
      }
    },
    async saveEmployee() {
      try {
        if (this.isEditing) {
          const id = this.employee.id.toString();
          await axios.put(`${this.apiUrl}/${id}`, this.employee);
        } else {
          const payload = {
            name: this.employee.name,
            designation: this.employee.designation,
            department: this.employee.department,
            salary: this.employee.salary,
          };
          await axios.post(this.apiUrl, payload);
        }
        await this.getEmployees();
        this.resetForm();
      } catch (error) {
        console.error('Save failed:', error);
        alert(`Save failed: ${error.response?.status} ${error.response?.data || error.message}`);
      }
    },
    editEmployee(emp) {
      this.employee = { ...emp };
      this.isEditing = true;
    },
    async deleteEmployee(id) {
      if (confirm(`Delete employee ${id}?`)) {
        try {
          await axios.delete(`${this.apiUrl}/${id}`);
          await this.getEmployees();
        } catch (error) {
          console.error('Delete failed:', error);
          alert('Delete failed');
        }
      }
    },
    async clearAllEmployees() {
      if (confirm(`Delete ALL ${this.employees.length} employees?`)) {
        try {
          for (const emp of this.employees) {
            await axios.delete(`${this.apiUrl}/${emp.id}`);
          }
          this.employees = [];
        } catch (error) {
          console.error('Clear all failed:', error);
        }
      }
    },
    resetForm() {
      this.employee = {
        id: null,
        name: "",
        designation: "",
        department: "",
        salary: 0,
      };
      this.isEditing = false;
    }
  }
};
</script>

<style scoped>
.container {
  max-width: 1200px;
}
.btn {
  border-radius: 6px;
}
</style>
